    // ---------- səhifə zolağı (çoxsəhifəli redaktə) ----------
    var pstrip = document.getElementById('ptabs') || document.getElementById('pstrip');
    function switchPage(i) {
      if (i < 0 || i >= state.pages.length || i === state.ai) return;
      state.ai = i;
      selIds = []; selId = null;
      renderAll();
    }
    function addPage() {
      pushHistory();
      state.pages.push({ id: 'pg-' + (++state.seq), name: t('new_page', 'Yeni səhifə'), bg: P().bg, elements: [] });
      switchPage(state.pages.length - 1);
    }
    function renamePage(i) {
      var n = window.prompt(t('page_rename', 'Səhifənin adı:'), state.pages[i].name);
      if (n && n.trim()) {
        pushHistory();
        state.pages[i].name = n.trim();
        renderAll();
      }
    }
    function deletePage(i) {
      if (state.pages.length <= 1) return; // son səhifə silinmir
      if (!window.confirm(t('page_del_confirm', 'Səhifə və içindəki elementlər silinsin?'))) return;
      pushHistory();
      var removedId = state.pages[i].id;
      state.pages.splice(i, 1);
      // Silinən səhifəyə işarə edən naviqasiya keçidlərini sıfırla.
      allElements().forEach(function (e2) {
        if (e2.props.pageId === removedId) { e2.props.action = 'none'; e2.props.pageId = ''; }
      });
      if (state.ai >= state.pages.length) state.ai = state.pages.length - 1;
      selIds = []; selId = null;
      renderAll();
    }
    function renderPstrip() {
      if (!pstrip) return;
      pstrip.innerHTML = '';
      state.pages.forEach(function (pg, i) {
        var b = el('button', 'ptab' + (i === state.ai ? ' on' : ''));
        b.type = 'button';
        b.appendChild(document.createTextNode(pg.name));
        b.addEventListener('click', function () { switchPage(i); });
        b.addEventListener('dblclick', function (e2) { e2.preventDefault(); renamePage(i); });
        if (state.pages.length > 1) {
          var x = el('span', 'px', '✕');
          x.title = t('page_del', 'Sil');
          x.addEventListener('click', function (e2) { e2.preventDefault(); e2.stopPropagation(); deletePage(i); });
          b.appendChild(x);
        }
        pstrip.appendChild(b);
      });
      var add = el('button', 'padd', '＋ ' + t('page_add', 'Səhifə əlavə et'));
      add.type = 'button';
      add.addEventListener('click', function (e2) { e2.preventDefault(); addPage(); });
      pstrip.appendChild(add);
    }

    function renderAll() {
      renderPstrip();
      renderCanvas();
      renderSidebar();
    }

