    // ---------- miqrasiya: v1 (bloklar) → v2 (tək səhifə) → v3 (pages[]) ----------
    function migrateV2(old) {
      var st = defaultState();
      st.title = old.page.title || st.title;
      st.fav = old.page.fav || '';
      st.css = old.css || '';
      st.w = num(old.page.w, 200, 4000, 960);
      st.h = num(old.page.h, 200, 4000, 700);
      st.pages[0].bg = old.page.bg || '#ffffff';
      st.pages[0].elements = (old.elements || []).filter(function (el2) {
        return el2 && typeof el2.type === 'string' && typeof el2.x === 'number';
      });
      st.seq = num(old.seq, 1, 1000000, 1);
      return st;
    }

    function migrateV1(old) {
      var seq = 0;
      var st = { page: { title: t('def_page_title', 'Açılış səhifəsi'), w: 960, h: 700, bg: '#ffffff' }, elements: [] };
      if (old.settings) {
        st.page.title = old.settings.title || st.page.title;
        if (/^#[0-9a-fA-F]{6}$/.test(old.settings.bg)) st.page.bg = old.settings.bg;
      }
      var y = 40;
      function put(type, w, h, props) {
        st.elements.push({ id: 'el-b' + (++seq), type: type, x: Math.round((960 - w) / 2), y: y, w: w, h: h, props: Object.assign(defaultProps(type), props) });
        y += h + 20;
      }
      (old.blocks || []).forEach(function (b) {
        if (!b) return;
        if (b.type === 'heading') put('text', 600, 50, { text: b.text || '', color: b.color || '#111827', align: b.align || 'left', fontSize: b.size === '3' ? '18' : b.size === '2' ? '24' : '32', fontWeight: '700' });
        else if (b.type === 'text') put('text', 600, 70, { text: b.text || '', color: b.color || '#333a45', align: b.align || 'left', fontSize: '15' });
        else if (b.type === 'image' && b.url) put('image', 400, 260, { url: b.url, alt: b.alt || '' });
        else if (b.type === 'button') put('button', 180, 46, { text: b.text || t('def_button', 'Düymə'), bg: b.bg || '#0067b8', color: b.color || '#ffffff', action: b.href ? 'url' : 'none', href: b.href || '' });
        else if (b.type === 'form') put('form', 330, 290, { title: b.title || '', userPh: b.userPh || '', passPh: b.passPh || '', btnText: b.btnText || t('def_btn', 'Daxil ol'), btnBg: b.btnBg || '#0067b8', btnColor: b.btnColor || '#ffffff' });
        else if (b.type === 'divider') put('line', 500, Math.max(1, parseInt(b.height, 10) || 2), {});
      });
      st.page.h = Math.max(700, y + 40);
      return st;
    }

    // ---------- dizayn təklifləri (avtomatik gözəlləşdirmə) ----------
    var sbTips = document.getElementById('sb-tips');

    function hexLum(hex) {
      var m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(String(hex || ''));
      if (!m) return null;
      var c = [parseInt(m[1], 16) / 255, parseInt(m[2], 16) / 255, parseInt(m[3], 16) / 255].map(function (v) {
        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
      });
      return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
    }
    function contrastRatio(a, b) {
      var la = hexLum(a), lb = hexLum(b);
      if (la == null || lb == null) return 21;
      return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
    }
    function contrastText(bg) {
      var l = hexLum(bg);
      if (l == null) return '#111827';
      return l > 0.35 ? '#111827' : '#ffffff';
    }

    function computeTips() {
      var tips = [];
      var els = ELS();
      var i;
      // Formu üfüqi mərkəzlə
      for (i = 0; i < els.length; i++) {
        if (els[i].type === 'form' && Math.abs(els[i].x + els[i].w / 2 - state.w / 2) > 10) {
          (function (f) {
            tips.push({ id: 'tip_center_form', apply: function () { f.x = Math.round((state.w - f.w) / 2); } });
          })(els[i]);
          break;
        }
      }
      // Sol kənarları hizala (yaxın-x qrupu)
      if (els.length >= 2) {
        var minX = Infinity, maxX = -Infinity;
        for (i = 0; i < els.length; i++) { minX = Math.min(minX, els[i].x); maxX = Math.max(maxX, els[i].x); }
        if (maxX - minX > 0 && maxX - minX <= 10) {
          tips.push({ id: 'tip_align_left', apply: function () { for (var j = 0; j < ELS().length; j++) ELS()[j].x = minX; } });
        }
      }
      // Enləri bərabərləşdir (yaxın-en qrupu)
      if (els.length >= 2) {
        var minW2 = Infinity, maxW2 = -Infinity;
        for (i = 0; i < els.length; i++) { minW2 = Math.min(minW2, els[i].w); maxW2 = Math.max(maxW2, els[i].w); }
        if (maxW2 - minW2 > 0 && maxW2 - minW2 <= 10) {
          tips.push({ id: 'tip_equal_width', apply: function () { for (var j = 0; j < ELS().length; j++) ELS()[j].w = maxW2; } });
        }
      }
      // Şaquli məsafələri bərabərləşdir (ütüşməyən, üst-üstə düzülmüş elementlər)
      var stacked = els.slice().sort(function (a, b) { return a.y - b.y; });
      var seqEls = [], lastBottom = -Infinity;
      for (i = 0; i < stacked.length; i++) {
        if (stacked[i].y >= lastBottom - 2) { seqEls.push(stacked[i]); lastBottom = stacked[i].y + stacked[i].h; }
      }
      if (seqEls.length >= 3) {
        var gaps = [];
        for (i = 1; i < seqEls.length; i++) gaps.push(seqEls[i].y - (seqEls[i - 1].y + seqEls[i - 1].h));
        var gMin = Math.min.apply(null, gaps), gMax = Math.max.apply(null, gaps);
        if (gMax - gMin > 8) {
          var avg = Math.round(gaps.reduce(function (a, b) { return a + b; }, 0) / gaps.length);
          tips.push({
            id: 'tip_spacing',
            apply: function () {
              var y = seqEls[0].y;
              for (var j = 0; j < seqEls.length; j++) { seqEls[j].y = y; y += seqEls[j].h + avg; }
            }
          });
        }
      }
      // Kontrast (mətn/fon nisbəti < 3 olan ilk element)
      for (i = 0; i < els.length; i++) {
        var e2 = els[i], p2 = e2.props;
        if (e2.type !== 'text' && e2.type !== 'rect' && e2.type !== 'button') continue;
        if (!p2.text) continue;
        var bg = e2.type === 'text' ? P().bg : p2.bg;
        if (contrastRatio(p2.color, bg) < 3) {
          (function (el3, bgc) {
            tips.push({ id: 'tip_contrast', apply: function () { el3.props.color = contrastText(bgc); } });
          })(e2, bg);
          break;
        }
      }
      return tips;
    }

    var PRESETS = [
      { id: 'preset_corp', pageBg: '#eef2f7', cardBg: '#ffffff', accent: '#1f4e79', text: '#1f2937', border: '#d0d7e2' },
      { id: 'preset_dark', pageBg: '#0f172a', cardBg: '#1e293b', accent: '#38bdf8', text: '#e2e8f0', border: '#334155' },
      { id: 'preset_minimal', pageBg: '#ffffff', cardBg: '#ffffff', accent: '#111827', text: '#111827', border: '#e5e7eb' },
      { id: 'preset_green', pageBg: '#f0fdf4', cardBg: '#ffffff', accent: '#16a34a', text: '#14532d', border: '#bbf7d0' }
    ];
    function applyPreset(pr) {
      P().bg = pr.pageBg;
      for (var i = 0; i < ELS().length; i++) {
        var e2 = ELS()[i], p = e2.props;
        if (e2.type === 'button') { p.bg = pr.accent; p.color = contrastText(pr.accent); }
        else if (e2.type === 'form') { p.bg = pr.cardBg; p.btnBg = pr.accent; p.btnColor = contrastText(pr.accent); p.inputBorder = pr.border; }
        else if (e2.type === 'rect') {
          var l = hexLum(p.bg);
          p.bg = (l != null && l > 0.5) ? pr.cardBg : pr.accent;
          p.color = contrastText(p.bg);
          if (num(p.borderW, 0, 40, 0) > 0) p.borderC = pr.border;
        }
        else if (e2.type === 'text') { p.color = pr.text; }
        else if (e2.type === 'line') { p.color = pr.border; }
      }
    }

    function tipRow(text, swatchColor, onClick) {
      var b = el('button', 'btip');
      b.type = 'button';
      if (swatchColor) {
        var sw = document.createElement('span');
        sw.style.cssText = 'display:inline-block;width:12px;height:12px;border-radius:50%;background:' + swatchColor + ';border:1px solid rgba(0,0,0,.15);flex:none';
        b.appendChild(sw);
      }
      b.appendChild(document.createTextNode(text));
      b.addEventListener('click', function (e2) {
        e2.preventDefault();
        pushHistory(); // hər təklif bir undo-addımıdır
        onClick();
        renderAll();
      });
      return b;
    }

    function renderTips() {
      if (!sbTips) return;
      sbTips.innerHTML = '';
      if (curVp) return; // dizayn təklifləri desktop layout üçündür
      var tips = computeTips();
      if (!tips.length && !ELS().length) return;
      sbTips.appendChild(el('div', 'btips-h', t('tips', 'Təkliflər')));
      tips.forEach(function (tip) {
        sbTips.appendChild(tipRow(t(tip.id, tip.id), null, tip.apply));
      });
      if (ELS().length) {
        sbTips.appendChild(el('div', 'btips-sub', t('tip_presets', 'Dizayn presetləri')));
        PRESETS.forEach(function (pr) {
          sbTips.appendChild(tipRow(t(pr.id, pr.id), pr.accent, function () { applyPreset(pr); }));
        });
      }
    }

    // ---------- şablon qalereyası ----------
    // Şablonlar v2 vəziyyətləridir: seçiləndə elementlər adi redaktə olunan
    // elementlərə çevrilir. Brendlər yalnız mətn/forma ilə çəkilir — xarici
    // şəkil YOXDUR (hədəf IP-si sızmamalıdır).
    function E(type, x, y, w, h, props) {
      return { id: '', type: type, x: x, y: y, w: w, h: h, props: Object.assign(defaultProps(type), props) };
    }

    // Brend loqoları: inline SVG data-URI (xarici sorğu yoxdur — hədəflərin
    // brauzeri üçüncü tərəfə müraciət etmir; canlı serverdə CSP yoxdur, admin
    // kanvasında img-src * data: icazəlidir). Google G / LinkedIn / Slack —
    // Wikimedia-dən real çoxrəngli SVG-lər; Dropbox / Zoom — simple-icons
    // qlifləri brend rəngində; Microsoft — dəqiq brend həndəsəsi ilə çəkilmiş
    // 4 kvadrat + mətn loqotipi. Loqotiplər sahiblərinə aiddir.
    var LOGO_MS = 'data:image/svg+xml;base64,';
    var LOGO_GOOGLE = 'data:image/svg+xml;base64,';

    // ---------- çoxsəhifəli ssenari fabrikləri ----------
    function PG(key, name, bg, els) { return { id: '', key: key, name: name, bg: bg, elements: els }; }
    function brandTpl(id, nameKey, nameDflt, title, fav, bg, els, css, h) {
      return { id: id, name: t(nameKey, nameDflt), brand: true, title: title, fav: fav, w: 960, h: h || 700, pages: [PG('home', t('home_page', 'Ana səhifə'), bg, els)], css: css || '' };
    }

    // Mobil reflow: fit-skriptini söndürür, elementlər axına düşür (elt mətnlər
    // avto-hündürlük; kartlar/şəkillər ölçülərini saxlayır). @tag tokenləri
    // şablon seçiləndə real element id-lərinə çevrilir.
    var MOBILE_CSS = '@media (max-width:560px){#pgfit{transform:none!important;height:auto!important}'
      + 'body{overflow-x:visible}'
      + '[data-pg]{width:100%!important;max-width:100%!important;height:auto!important;min-height:100vh;overflow:visible;padding:16px 0}'
      + '[data-pg]>.elr,[data-pg]>.elf,[data-pg]>.elb,[data-pg]>.ell,[data-pg]>.elv{position:static!important;width:100%!important;max-width:100%!important;margin:0 0 12px!important}'
      + '[data-pg]>.elt{position:static!important;width:100%!important;max-width:100%!important;margin:0 0 12px!important;height:auto!important}'
